use std::io::{self, Read};

fn solve(x: i32) -> i32 {
    // Convert the number to a string so we can determine its digit and length.
    let s = x.to_string();
    let k = s.len() as i32;                                 // number of repetitions
    let d = s.chars().next().unwrap().to_digit(10).unwrap() as i32; // the repeated digit

    // For each digit less than d, we type lengths 1,2,3,4 → sum = 10.
    // Then for digit d itself, we type lengths 1..=k → sum = k*(k+1)/2.
    (d - 1) * 10 + k * (k + 1) / 2
}

fn main() {
    // Read the single input integer.
    let mut buf = String::new();
    io::stdin().read_to_string(&mut buf).unwrap();
    let x: i32 = buf.trim().parse().unwrap();

    // Compute and print the result.
    let result = solve(x);
    println!("{}", result);
}